(409, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 301, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":301,\"component_id\":13,\"name\":\"quote\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":null,\"group\":\"2\",\"schema_group\":1,\"schema_instance\":1,\"position\":5,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-03-13T06:55:32.000000Z\",\"updated_at\":\"2026-03-13T06:55:32.000000Z\"}}', NULL, '2026-03-13 06:55:32', '2026-03-13 06:55:32'),
(410, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 302, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":302,\"component_id\":13,\"name\":\"discription\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"Lift is no longer just a means of going up and down. It has blended with urban lifestyle. Modern buildings are designed with lots of emotion mixed with our culture and heritage.\",\"group\":\"2\",\"schema_group\":2,\"schema_instance\":1,\"position\":6,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-03-13T06:55:32.000000Z\",\"updated_at\":\"2026-03-13T06:55:32.000000Z\"}}', NULL, '2026-03-13 06:55:32', '2026-03-13 06:55:32'),
(411, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 303, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":303,\"component_id\":13,\"name\":\"discription\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"A lift is considered as a heart of a building. Urban life stands still if the lift does not provide uninterrupted services. Thus lift business is stepping into the next level in order to keep pace with modern lifestyle.\",\"group\":\"2\",\"schema_group\":2,\"schema_instance\":2,\"position\":7,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-03-13T06:55:32.000000Z\",\"updated_at\":\"2026-03-13T06:55:32.000000Z\"}}', NULL, '2026-03-13 06:55:32', '2026-03-13 06:55:32'),
(412, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 304, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":304,\"component_id\":13,\"name\":\"discription\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"Our commitment to quality and safety is unwavering. We partner with the world\'s leading brands to ensure that every installation meets the highest international standards. Our team of dedicated professionals works tirelessly to provide seamless service from consultation to after-sales support.\",\"group\":\"2\",\"schema_group\":2,\"schema_instance\":3,\"position\":8,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-03-13T06:55:32.000000Z\",\"updated_at\":\"2026-03-13T06:55:32.000000Z\"}}', NULL, '2026-03-13 06:55:33', '2026-03-13 06:55:33'),
(413, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 305, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":305,\"component_id\":13,\"name\":\"discription\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"Thank you for trusting RAR Lift as your vertical mobility partner. We look forward to elevating your projects to new heights.\",\"group\":\"2\",\"schema_group\":2,\"schema_instance\":4,\"position\":9,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-03-13T06:55:33.000000Z\",\"updated_at\":\"2026-03-13T06:55:33.000000Z\"}}', NULL, '2026-03-13 06:55:33', '2026-03-13 06:55:33'),
