(2999, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 1731, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":1731,\"component_id\":4,\"name\":\"origin\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"Greece\",\"group\":\"11\",\"schema_group\":1,\"schema_instance\":1,\"position\":3,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-04-15T06:04:59.000000Z\",\"updated_at\":\"2026-04-15T06:04:59.000000Z\"}}', NULL, '2026-04-15 06:04:59', '2026-04-15 06:04:59'),
(3000, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 1732, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":1732,\"component_id\":4,\"name\":\"type\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"Premium Partner\",\"group\":\"11\",\"schema_group\":1,\"schema_instance\":1,\"position\":4,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-04-15T06:04:59.000000Z\",\"updated_at\":\"2026-04-15T06:04:59.000000Z\"}}', NULL, '2026-04-15 06:04:59', '2026-04-15 06:04:59'),
(3001, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 1733, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":1733,\"component_id\":4,\"name\":\"description_1\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"Having been established in 1983 in Kilkis, Greece,  KLEEMANN is one of the most important lift manufacturers in European and global markets, offering any kind of lift for residential and commercial use, for persons or freight,  as well as lifting systems, escalators and moving walks, marine lifts, and other lifts of special requirements.\",\"group\":\"11\",\"schema_group\":1,\"schema_instance\":1,\"position\":5,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-04-15T06:04:59.000000Z\",\"updated_at\":\"2026-04-15T06:04:59.000000Z\"}}', NULL, '2026-04-15 06:04:59', '2026-04-15 06:04:59'),
(3002, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 1734, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":1734,\"component_id\":4,\"name\":\"description_2\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"KLEEMANN was established in 1983 after signing a contract with the German company Kleemann Hubtechnik GmbH, obtaining this way the license and the right to use their know-how and brand name.\\u000bOur commitment for efficiency, structure and discipline is therefore owed to our Northern Europe origin while we derive our passion, warmth and creativity from our Mediterranean side.\\u000b\\u000bWe never cut our name in pieces. We admire its story and what it represents. We show our respect to KLEEMANN by always referring to it in upper cases, no exceptions allowed. We also keep it uniform and undivided.\",\"group\":\"11\",\"schema_group\":1,\"schema_instance\":1,\"position\":6,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-04-15T06:04:59.000000Z\",\"updated_at\":\"2026-04-15T06:04:59.000000Z\"}}', NULL, '2026-04-15 06:04:59', '2026-04-15 06:04:59'),
