(3975, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 2194, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":2194,\"component_id\":\"29\",\"name\":\"title\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":\"0\",\"value\":\"Elevating the Future, Together.\",\"group\":\"2\",\"schema_group\":\"1\",\"schema_instance\":\"1\",\"position\":\"4\",\"show_in_table\":\"1\",\"colspan\":\"6\",\"page_id\":null,\"created_at\":\"2026-04-18T09:25:30.000000Z\",\"updated_at\":\"2026-04-18T09:25:30.000000Z\"}}', NULL, '2026-04-18 15:25:30', '2026-04-18 15:25:30'),
(3976, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 2195, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":2195,\"component_id\":\"29\",\"name\":\"quote\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":\"0\",\"value\":\"We, at RAR Lift, keeping in mind all the above requirements brought to you a customized solution for your lift and lifestyle.\",\"group\":\"2\",\"schema_group\":\"1\",\"schema_instance\":\"1\",\"position\":\"5\",\"show_in_table\":\"1\",\"colspan\":\"6\",\"page_id\":null,\"created_at\":\"2026-04-18T09:25:30.000000Z\",\"updated_at\":\"2026-04-18T09:25:30.000000Z\"}}', NULL, '2026-04-18 15:25:30', '2026-04-18 15:25:30'),
(3977, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 2196, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":2196,\"component_id\":\"29\",\"name\":\"discription\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":\"0\",\"value\":\"Lift is no longer just a means of going up and down. It has blended with urban lifestyle. Modern buildings are designed with lots of emotion mixed with our culture and heritage.\",\"group\":\"2\",\"schema_group\":\"2\",\"schema_instance\":\"1\",\"position\":\"6\",\"show_in_table\":\"1\",\"colspan\":\"6\",\"page_id\":null,\"created_at\":\"2026-04-18T09:25:30.000000Z\",\"updated_at\":\"2026-04-18T09:25:30.000000Z\"}}', NULL, '2026-04-18 15:25:30', '2026-04-18 15:25:30'),
(3978, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 2197, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":2197,\"component_id\":\"29\",\"name\":\"discription\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":\"0\",\"value\":\"A lift is considered as a heart of a building. Urban life stands still if the lift does not provide uninterrupted services. Thus lift business is stepping into the next level in order to keep pace with modern lifestyle.\",\"group\":\"2\",\"schema_group\":\"2\",\"schema_instance\":\"2\",\"position\":\"7\",\"show_in_table\":\"1\",\"colspan\":\"6\",\"page_id\":null,\"created_at\":\"2026-04-18T09:25:30.000000Z\",\"updated_at\":\"2026-04-18T09:25:30.000000Z\"}}', NULL, '2026-04-18 15:25:30', '2026-04-18 15:25:30'),
(3979, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 2198, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":2198,\"component_id\":\"29\",\"name\":\"discription\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":\"0\",\"value\":\"Our commitment to quality and safety is unwavering. We partner with the world\'s leading brands to ensure that every installation meets the highest international standards. Our team of dedicated professionals works tirelessly to provide seamless service from consultation to after-sales support.\",\"group\":\"2\",\"schema_group\":\"2\",\"schema_instance\":\"3\",\"position\":\"8\",\"show_in_table\":\"1\",\"colspan\":\"6\",\"page_id\":null,\"created_at\":\"2026-04-18T09:25:30.000000Z\",\"updated_at\":\"2026-04-18T09:25:30.000000Z\"}}', NULL, '2026-04-18 15:25:30', '2026-04-18 15:25:30'),
(3980, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 2199, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":2199,\"component_id\":\"29\",\"name\":\"discription\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":\"0\",\"value\":\"Thank you for trusting RAR Lift as your vertical mobility partner. We look forward to elevating your projects to new heights.\",\"group\":\"2\",\"schema_group\":\"2\",\"schema_instance\":\"4\",\"position\":\"9\",\"show_in_table\":\"1\",\"colspan\":\"6\",\"page_id\":null,\"created_at\":\"2026-04-18T09:25:30.000000Z\",\"updated_at\":\"2026-04-18T09:25:30.000000Z\"}}', NULL, '2026-04-18 15:25:30', '2026-04-18 15:25:30'),
