(4989, 'componentfield', 'updated', 'App\\Models\\ComponentField', 'updated', 274, 'App\\Models\\User', 1, '{\"attributes\":{\"value\":\"Ready to Elevate Your Building?\",\"updated_at\":\"2026-05-20T18:31:32.000000Z\"},\"old\":{\"value\":\"Ready to Discuss Your Project?\",\"updated_at\":\"2026-03-13T00:32:41.000000Z\"}}', NULL, '2026-05-21 00:31:32', '2026-05-21 00:31:32'),
(4990, 'componentfield', 'updated', 'App\\Models\\ComponentField', 'updated', 275, 'App\\Models\\User', 1, '{\"attributes\":{\"value\":\"Whether you are planning a new project or need reliable service for an existing elevator, RARlift is ready to help. Contact our team for expert consultation, product recommendation, and a customized quotation.\",\"updated_at\":\"2026-05-20T18:31:32.000000Z\"},\"old\":{\"value\":\"Whether you need a new installation, modernization, or reliable maintenance, our team of experts is ready to provide the perfect vertical mobility solution tailored to your specific needs.\",\"updated_at\":\"2026-03-13T00:32:41.000000Z\"}}', NULL, '2026-05-21 00:31:32', '2026-05-21 00:31:32'),
(4991, 'componentfield', 'updated', 'App\\Models\\ComponentField', 'updated', 276, 'App\\Models\\User', 1, '{\"attributes\":{\"value\":\"Get a Free Quote\",\"updated_at\":\"2026-05-20T18:31:32.000000Z\"},\"old\":{\"value\":\"Send a Message\",\"updated_at\":\"2026-03-13T00:32:41.000000Z\"}}', NULL, '2026-05-21 00:31:32', '2026-05-21 00:31:32'),
