(1725, 4, 'portfolio_image', 'upload', NULL, NULL, NULL, NULL, NULL, 0, 'd923ef12c6edeeb3f0e9a0d54d5df1bb.webp', '10', 6, 5, 67, 1, 6, NULL, '2026-04-13 12:16:04', '2026-05-02 10:17:10'),
(1726, 4, 'description_1', 'text', NULL, NULL, NULL, NULL, NULL, 0, 'We are proud to announce EITA Resources Berhad\'s successful listing on the Main Board of Kuala Lumpur Stock Exchange (KLSE) on 9th April 2012. As a subsidiary, EITA Elevator (Malaysia) Sdn Bhd takes great pride in being the first homegrown elevator company to be listed on KLSE and marketed under our very own brand name. EITA Elevator markets, designs, manufactures, installs, commissions, services and modernizes a wide range of elevators, escalators and travelators - your one-stop solution provider.', '10', 1, 1, 5, 1, 6, NULL, '2026-04-15 05:26:12', '2026-04-15 05:26:12'),
(1727, 4, 'description_2', 'text', NULL, NULL, NULL, NULL, NULL, 0, 'EITA Elevator has built a strong track record and reputation in our local Malaysian market and we have also expanded our market coverage to various countries in the ASEAN region and the Middle East. Since our formation, we have grown from strength to strength and now have many successful installations in government complexes, commercial buildings, education campuses, hospitals, transportation hubs, shopping centres, hotels, condominiums, home lifts and many more. We have also adopted Green Technology to be more environmental friendly and to help our customers save cost, especially in the areas of energy efficient equipment and regenerative solutions.', '10', 1, 1, 6, 1, 6, NULL, '2026-04-15 05:26:12', '2026-04-15 05:26:12'),
(1728, 4, 'brand_logo', 'upload', NULL, NULL, NULL, NULL, NULL, 0, 'cb3ceb9acbb3a043f60abaacf38bd721.webp', '11', 1, 1, 0, 1, 6, NULL, '2026-04-15 06:04:59', '2026-04-15 06:04:59'),
(1729, 4, 'brand_name', 'text', NULL, NULL, NULL, NULL, NULL, 0, 'Kleemann', '11', 1, 1, 1, 1, 6, NULL, '2026-04-15 06:04:59', '2026-04-15 06:04:59'),
(1730, 4, 'origin_flag', 'upload', NULL, NULL, NULL, NULL, NULL, 0, 'e18dbb380f406fd01d4ce415aebc8452.webp', '11', 1, 1, 2, 1, 6, NULL, '2026-04-15 06:04:59', '2026-04-15 06:04:59'),
(1731, 4, 'origin', 'text', NULL, NULL, NULL, NULL, NULL, 0, 'Greece', '11', 1, 1, 3, 1, 6, NULL, '2026-04-15 06:04:59', '2026-04-15 06:04:59'),
(1732, 4, 'type', 'text', NULL, NULL, NULL, NULL, NULL, 0, 'Premium Partner', '11', 1, 1, 4, 1, 6, NULL, '2026-04-15 06:04:59', '2026-04-15 06:04:59'),
(1733, 4, 'description_1', 'text', NULL, NULL, NULL, NULL, NULL, 0, 'Having been established in 1983 in Kilkis, Greece,  KLEEMANN is one of the most important lift manufacturers in European and global markets, offering any kind of lift for residential and commercial use, for persons or freight,  as well as lifting systems, escalators and moving walks, marine lifts, and other lifts of special requirements.', '11', 1, 1, 5, 1, 6, NULL, '2026-04-15 06:04:59', '2026-04-15 06:04:59'),
(1734, 4, 'description_2', 'text', NULL, NULL, NULL, NULL, NULL, 0, 'KLEEMANN was established in 1983 after signing a contract with the German company Kleemann Hubtechnik GmbH, obtaining this way the license and the right to use their know-how and brand name.INSERT INTO `component_fields` (`id`, `component_id`, `name`, `type`, `relationship_type`, `related_component`, `display_column`, `static_options`, `help_text`, `is_required`, `value`, `group`, `schema_group`, `schema_instance`, `position`, `show_in_table`, `colspan`, `page_id`, `created_at`, `updated_at`) VALUES
