INSERT INTO `pages` (`id`, `name`, `permalink`, `description`, `page_text_content`, `status`, `is_breadcrumb`, `image`, `seo_title`, `seo_description`, `seo_image`, `seo_index`, `header_component`, `header_component_position`, `footer_component`, `created_at`, `updated_at`) VALUES
(1, 'Home', '/', '<p><br></p>', '<p><br></p>', '1', 0, NULL, NULL, NULL, NULL, 'noindex', 'header', NULL, 'footer', '2026-03-09 09:39:52', '2026-03-09 09:41:04'),
(2, 'products', 'products', '<span style=\"background-color: rgb(255, 255, 255); font-size: clamp(2.625rem, 1.5vw + 2rem, 3rem); font-weight: bold; display: inline-block; padding: 0 5px; margin-bottom: 1rem;\">\r\n    Comprehensive Product Range\r\n</span>\r\n\r\n<p style=\"line-height: 1.2; margin-bottom: 0.5rem;\">\r\n    <span style=\"background-color: rgb(255, 255, 255); font-size: clamp(0.8125rem, 0.6vw + 0.7rem, 1rem); display: inline-block; padding: 2px 5px;\">\r\n        From standard passenger lifts to specialized industrial elevators, we provide tailored\r\n    </span>\r\n</p>\r\n\r\n<p style=\"line-height: 1.2;\">\r\n    <span style=\"background-color: rgb(255, 255, 255); font-size: clamp(0.8125rem, 0.6vw + 0.7rem, 1rem); display: inline-block; padding: 2px 5px;\">\r\n        solutions to meet your specific architectural and functional requirements.\r\n    </span>\r\n</p>', '<p><br></p>', '1', 1, NULL, NULL, NULL, NULL, 'noindex', 'header', 'fix', 'footer', '2026-03-12 19:30:30', '2026-05-06 10:03:33'),
(3, 'about', 'about', '<span style=\"background-color: rgb(255, 255, 255); font-size: clamp(2.625rem, 1.5vw + 2rem, 3rem);\">\r\n    Elevating Every Journey\r\n</span>\r\n\r\n<p style=\"line-height: 1\">\r\n    <span style=\"background-color: rgb(255, 255, 255); font-size: clamp(0.8125rem, 0.6vw + 0.7rem, 1rem);\">\r\n        At RarLift, we combine cutting-edge engineering with sleek design to redefine vertical transportation.\r\n    </span>\r\n</p>\r\n\r\n<p style=\"line-height: 1\">\r\n    <span style=\"background-color: rgb(255, 255, 255); font-size: clamp(0.8125rem, 0.6vw + 0.7rem, 1rem);\">\r\n        Our commitment to safety, reliability, and innovation ensures that every floor you reach is a step toward excellence.​\r\n    </span>\r\n</p>', '<p><br></p>', '1', 1, NULL, NULL, NULL, NULL, 'noindex', 'header', 'fix', 'footer', '2026-03-13 05:57:09', '2026-05-06 07:01:40'),
(6, 'brands', 'brands', '<p><br></p>', '<p><br></p>', '1', 0, NULL, NULL, NULL, NULL, 'noindex', 'header', 'fix', 'footer', '2026-03-13 10:18:25', '2026-03-13 10:18:57'),
(7, 'decoration', 'decoration', '<p><br></p>', '<p><br></p>', '1', 0, NULL, NULL, NULL, NULL, 'noindex', 'header', 'fix', 'footer', '2026-03-13 10:29:25', '2026-04-13 09:13:23'),
(8, 'Portfolio', 'portfolio', '<span style=\"background-color: rgb(255, 255, 255); font-size: clamp(2.625rem, 1.5vw + 2rem, 3rem); font-weight: bold; display: inline-block; padding: 0 5px; margin-bottom: 1rem;\">\r\n    Diverse Project Portfolio\r\n</span>\r\n\r\n<p style=\"line-height: 1.2; margin-bottom: 0.5rem;\">\r\n    <span style=\"background-color: rgb(255, 255, 255); font-size: clamp(0.8125rem, 0.6vw + 0.7rem, 1rem); display: inline-block; padding: 2px 5px;\">\r\n        From luxury residential lifts to high-capacity freight elevators, explore how we \r\n    </span>\r\n</p>\r\n\r\n<p style=\"line-height: 1.2;\">\r\n    <span style=\"background-color: rgb(255, 255, 255); font-size: clamp(0.8125rem, 0.6vw + 0.7rem, 1rem); display: inline-block; padding: 2px 5px;\">\r\n        have successfully engineered vertical mobility for complex architectural designs.\r\n    </span>\r\n</p>', '<p><br></p>', '1', 1, NULL, NULL, NULL, NULL, 'noindex', 'header', 'fix', 'footer', '2026-03-13 10:33:43', '2026-06-13 16:10:32'),
(9, 'contact', 'contact', '<p><br></p>', '<p><br></p>', '1', 1, NULL, NULL, NULL, NULL, 'noindex', 'header', 'fix', 'footer', '2026-03-14 13:22:43', '2026-03-15 03:22:30'),
(10, 'gallery', 'gallery', NULL, NULL, '1', 0, NULL, NULL, NULL, NULL, 'noindex', 'header', 'fix', 'footer', '2026-04-08 10:31:05', '2026-04-15 09:36:29');
